export default meta;
type Story = StoryObj;

// Colors
export const Colors: Story = {
  render: () => {
    const colors = theme.colors;

    const colorGroups = {
      "Brand Colors": [
        'obolGreen', 'obolMidGreen', 'obolGreenHover', 'obolGreenLight',
        'obolDarkDark', 'obolBlue', 'obolGold', 'obolDisabled'
      ],
      "Figma Synced Colors (New!)": [
        'purpleLight', 'purpleLightHover', 'tealDark', 'purpleDark', 'grayMedium'
      ],
      "Background Colors": [
        'bg01', 'bg02', 'bg03', 'bg04', 'bg05',
        'primaryBgDefault', 'primaryBgDefaultHover', 'secondaryBgDefault',
        'grayBgDefault', 'gray2BgDefault', 'cardBackgroundDark', 'cardBackgroundLight'
      ],
      "Text Colors": [
        'textMiddle', 'textLight', 'textLighter', 'textGreenDark',
        'textGreenLight', 'textGreen1', 'textGreen2', 'textGreen3',
        'primaryTextDefault', 'textGreenHover', 'textCreateHover', 'textGrayHover'
      ],
      "Semantic Colors": [
        'coordinate', 'coordinateHover', 'test', 'testHover',
        'create', 'createHover', 'linkButtonHover', 'txButton'
      ],
      "UI Colors": [
        'navButtonBgDefault', 'navButtonBgHover', 'light', 'body',
        'muted', 'menu', 'tooltip', 'tooltip2', 'lightGrey'
      ],
      "Gradients": [
        'gradientGold', 'gradientSilver', 'gradientBronze'
      ],
      "Base Colors": [
        'white', 'black', 'lightBackground'
      ],
    };

    return (
      <Box css={{ p: '$lg' }}>
        {Object.entries(colorGroups).map(([groupName, colorNames]) => (
          <Box key={groupName} css={{ mb: '$3xl' }}>
            <Text variant="h4" css={{ mb: '$lg' }}>
              {groupName}
              {groupName === "Figma Synced Colors (New!)" && (
                <Text
                  inline
                  css={{
                    ml: '$sm',
                    fontSize: '$3',
                    color: '$obolGreen',
                    backgroundColor: '$bg03',
                    px: '$xs',
                    py: '2px',
                    borderRadius: '$1',
                  }}
                >
                  Synced from Figma
                </Text>
              )}
            </Text>

            <Flex css={{ flexWrap: 'wrap', gap: '$md' }}>
              {colorNames.map(colorName => {
                const colorToken: any = colors[colorName as keyof typeof colors];
                const colorValue = typeof colorToken === 'object' && colorToken?.value ? colorToken.value : String(colorToken);

                // Skip if no value
                if (!colorValue) return null;

                const isGradient = colorName.includes('gradient');

                return (
                  <Box
                    key={colorName}
                    css={{
                      width: '180px',
                      border: '1px solid $bg04',
                      borderRadius: '$2',
                      overflow: 'hidden',
                      backgroundColor: '$bg02',
                      transition: 'transform 0.2s',
                      '&:hover': {
                        transform: 'translateY(-2px)',
                        boxShadow: '0 4px 12px rgba(0,0,0,0.3)',
                      }
                    }}
                  >
                    {/* Color swatch */}
                    <Box
                      css={{
                        height: '100px',
                        background: isGradient ? colorValue : undefined,
                        backgroundColor: isGradient ? undefined : colorValue,
                        border: colorValue === '#fff' || colorValue === '#ffffff' ? '1px solid $bg04' : 'none',
                      }}
                    />

                    {/* Color info */}
                    <Box css={{ p: '$sm' }}>
                      <Text
                        variant="metadata"
                        css={{
                          fontFamily: '$mono',
                          fontSize: '11px',
                          color: '$textLight',
                          mb: '2px',
                        }}
                      >
                        ${colorName}
                      </Text>
                      <Text
                        variant="metadata"
                        css={{
                          fontSize: '10px',
                          color: '$textMiddle',
                          wordBreak: 'break-all',
                        }}
                      >
                        {isGradient ? 'gradient' : colorValue}
                      </Text>
                    </Box>
                  </Box>
                );
              })}
            </Flex>
          </Box>
        ))}
      </Box>
    );
  },
  parameters: {
    docs: {
      description: {
        story: 'All color tokens in the design system, organized by category. Includes brand colors, backgrounds, text colors, and recently synced Figma colors.',
      },
    },
  },
};

